{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a torn map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk, Mara crouches over a brittle parchment, brass compass spinning wildly, the broken skyline of the city behind her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp wakes with a warning.",
      "visual_description": "A small oil lamp flickers to life on Mara's pack, its single flame-eye narrowed, casting long shadows across the map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox is wound up for scouting.",
      "visual_description": "A clockwork fox with blue glass eyes stretches as its key-wind tail clicks, standing on a cracked cobblestone at the city's outer wall.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps out of a broken pane as if from water, coat shimmering with reflections of broken city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the castle gates.",
      "visual_description": "Towering iron gates hang half off their hinges, royal crests rusted; Tin Fox sniffs the threshold while Mara raises the oracle lamp.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower looms in the smoke.",
      "visual_description": "A leaning tower wreathed in green mist; the oracle lamp's eye widens, light bending toward the doorway.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of scaled wings echo through ruined streets.",
      "visual_description": "Massive claw marks gouge a marble plaza; the glass diver crouches by the prints while Tin Fox's ears swivel toward distant roars.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Old royal banners hang in tatters above a courtyard.",
      "visual_description": "Faded crimson banners flap over a frozen fountain; Mara sketches the layout while the oracle lamp glows steady at her shoulder.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened faces peek from boarded windows.",
      "visual_description": "Pale, hollow-cheeked figures duck behind shutters as the glass diver passes, his reflective coat catching their candlelight.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The team finds the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "An official snores at a tilted desk, ledger book as pillow, stamped papers stuck to his sleeves and cheek; Tin Fox tilts its head in confusion.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol clanks down the avenue.",
      "visual_description": "Shadows of plated figures move past a broken colonnade; the glass diver pulls Mara into a mirrored alcove while the oracle lamp dims to a pinprick.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox slips through a grate to scout ahead.",
      "visual_description": "The clockwork fox squeezes between iron bars, key-wind tail glinting, blue glass eyes throwing two narrow beams down a flooded corridor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door pulses with sealed runes.",
      "visual_description": "A tall stone door etched with shifting symbols hums in a vaulted hall; the oracle lamp's flame leans toward one specific glyph.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver dives through a mirror beyond the door.",
      "visual_description": "Rippling silver swallows the diver headfirst, his coat fanning out like a stingray, helmet catching fractured reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside the inner chamber, the sleeping tax collector is bundled up for rescue.",
      "visual_description": "The glass diver hoists the dozing official onto his back; the ledger book flops, stamped papers fluttering like loose feathers.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox leads the retreat through a collapsing hall.",
      "visual_description": "Dust rains from cracked vaults as the clockwork fox sprints ahead, blue eye-beams cutting through falling debris, Mara close behind.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle lamp shouts a final warning at the bridge.",
      "visual_description": "A long stone bridge sways above a black river; the lamp's flame-eye flares wide, illuminating cracks splitting under their feet.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross to safety as the ruined city fades behind them.",
      "visual_description": "Silhouettes on the far bank at dawn: Mara with her compass, the glass diver carrying the still-snoring official, Tin Fox at their heels, the oracle lamp glowing softly.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    }
  ]
}

